from bisect import bisect_left

def solve_feed_passes(text):
    data = list(map(int, text.split()))
    n, prices = data[0], data[1:4]
    days = data[4:4 + n]
    best = [0] * (n + 1)      # best[i]: cheapest cover of days[i:]
    for i in range(n - 1, -1, -1):
        best[i] = min(p + best[bisect_left(days, days[i] + length)]
                      for p, length in zip(prices, (1, 7, 30)))
    return str(best[0])

