def solve_feed_passes(text):
    data = list(map(int, text.split()))
    n, prices = data[0], data[1:4]
    days = set(data[4:4 + n])
    if not days:
        return '0'
    best = {}
    for d in range(max(days), 0, -1):
        if d in days:
            best[d] = min(prices[0] + best.get(d + 1, 0),
                          prices[1] + best.get(d + 7, 0),
                          prices[2] + best.get(d + 30, 0))
        else:
            best[d] = best.get(d + 1, 0)
        best.pop(d + 31, None)
    return str(best[1])
